<details><summary>Show detailed Job Card / ROT register ({{ count($rows) }})</summary><div class="table-wrap"><table><thead><tr><th>Staff</th><th>JC No.</th><th>ROT</th><th>Standard</th><th>Productive</th><th>Total TAT</th><th>Status</th></tr></thead><tbody>@foreach($rows as $r)<tr><td>{{ $r['staff_name'] }}</td><td>{{ $r['job_no'] }}</td><td>{{ $r['rot_code'] }} · {{ $r['description'] }}</td><td>{{ $r['shared_rot']?'Shared ROT':($r['standard_hours'] ?? '—') }}</td><td>{{ $r['productive_hours'] }}</td><td>{{ $r['tat_hours'] ?? '—' }}</td><td>{{ $r['status'] }}</td></tr>@endforeach</tbody></table></div></details></section>
<section id="leave" class="card"><h2>🌴 Staff Leave Ledger</h2><p class="muted">Positive = earned leave, negative = leave used. An advance/negative balance remains negative. Leave without an application is flagged separately; credits are not automatically invented from attendance.</p><div class="table-wrap"><table><thead><tr><th>Employee</th><th>Earned</th><th>Used</th><th>Balance</th><th>No Application</th></tr></thead><tbody>@foreach($balances as $p)<tr><td>{{ $p['name'] }} · {{ $p['staff_code'] }}</td><td>{{ $p['earned'] }}</td><td>{{ $p['used'] }}</td><td class="{{ $p['balance']<0?'bad':'good' }}">{{ $p['balance'] }}</td><td class="{{ $p['without_application']>0?'bad':'' }}">{{ $p['without_application'] }}</td></tr>@endforeach</tbody></table></div>
